% A_dRSA_alt.m
%
% Purpose:
%   Run optional single-model real-neural dRSA analyses for selected
%   conditions and MEGIN sensor groups. This script consumes the Stage-07
%   handoff generated by 07_run_matlab_drsa.py and is intended for exploratory
%   sensor-group checks that are independent of the main A_dRSA.m outputs.
%
% Usage examples:
%   % Direct MATLAB run after Python handoff generation:
%   drsa_handoff_json = '/Volumes/MORWUR/Projects/DAMIANO/Attention/derivatives/reports/sub-04/ses-01/07_matlab_drsa_handoff.json';
%   conditions_to_run = {'always_visible', 'occluded_nondeviant'};
%   sensor_groups_to_run = {'wholeBrain', 'occipital'};
%   path_type = 'observed'; % observed, predicted, prediction_error, or pe_* variant
%   dRSAtypeToRun = 'corr';
%   run('/Users/damiano/Documents/UniTn/Dynamo/Attention/DAD/meg/code/analysis/A_dRSA_alt.m');
%
%   % Prediction-error alt dRSA for the occluded-deviant question:
%   conditions_to_run = {'occluded_deviant'};
%   sensor_groups_to_run = {'wholeBrain'};
%   path_type = 'prediction_error';
%   dRSAtypeToRun = 'corr';
%   run('/Users/damiano/Documents/UniTn/Dynamo/Attention/DAD/meg/code/analysis/A_dRSA_alt.m');
%
%   % 50/50 constrained-prior PE alt dRSA for occluded-deviant trials:
%   conditions_to_run = {'occluded_deviant'};
%   sensor_groups_to_run = {'wholeBrain'};
%   path_type = 'pe_prior_constrained_50';
%   dRSAtypeToRun = 'corr';
%   run('/Users/damiano/Documents/UniTn/Dynamo/Attention/DAD/meg/code/analysis/A_dRSA_alt.m');
%
% Inputs:
%   - drsa_handoff_json generated by 07_run_matlab_drsa.py.
%   - Stage-06 neural MAT/JSON outputs.
%   - Observed trajectory MAT referenced by the handoff. Its matched
%     occluded_nondeviant trials supply the expected continuation.
%
% Outputs:
%   <drsa_dir>/matlab_real_neural/A_dRSA_alt/<condition>/<drsa_type>/...
%     for always_visible and occluded_nondeviant observed-model outputs.
%   <drsa_dir>/matlab_real_neural/A_dRSA_alt/occluded_deviant/<source>/<drsa_type>/...
%     for observed actual-deviant, expected/predicted, legacy
%     prediction-error, and explicit PE-variant occluded-deviant outputs.
%   Each PNG title and y-axis state the stimulus model label, for example
%   "actual deviant position", "expected/predicted position", or
%   "prediction error position".
%   Occluded-condition matrix PNGs include dashed horizontal lines marking
%   first complete occlusion and first reappearance from the handoff timing.
%
% Data flow:
%   handoff JSON -> one condition neural tensor -> NaN-channel cleanup ->
%   sensor-group selection -> one trajectory position model -> dRSA PNG/MAT.
%   Prediction-error runs build the model as observed occluded-deviant position
%   minus expected/predicted occluded-nondeviant position before dRSA. New PE
%   variants keep that legacy source unchanged and write distinct model-source
%   folders, labels, and result metadata.

%% Reset workspace while preserving explicit runtime overrides
clearvars -except drsa_handoff_json conditions_to_run sensor_groups_to_run path_type dRSAtypeToRun plotSampleRateHz pcrStrategy doSmoothNeural smoothWindowSamples doSmoothingPlots plotSmoothingWindow output_root_override

%% Runtime defaults and handoff
if ~exist('drsa_handoff_json', 'var') || isempty(drsa_handoff_json)
    error('Set drsa_handoff_json before running A_dRSA_alt.m.');
end
if ~exist('conditions_to_run', 'var') || isempty(conditions_to_run)
    conditions_to_run = {'always_visible', 'occluded_nondeviant', 'occluded_deviant'};
end
if ischar(conditions_to_run) || isstring(conditions_to_run)
    conditions_to_run = cellstr(conditions_to_run);
end
if ~exist('sensor_groups_to_run', 'var') || isempty(sensor_groups_to_run)
    sensor_groups_to_run = {'wholeBrain'};
end
if ischar(sensor_groups_to_run) || isstring(sensor_groups_to_run)
    sensor_groups_to_run = cellstr(sensor_groups_to_run);
end
if ~exist('path_type', 'var') || isempty(path_type), path_type = 'observed'; end
path_type = lower(strtrim(char(path_type)));
if strcmp(path_type, 'pe')
    path_type = 'prediction_error';
end
valid_path_types = { ...
    'observed', 'predicted', 'prediction_error', ...
    'pe_prior_unconstrained_50', ...
    'pe_prior_constrained_50', ...
    'pe_precision_weighted', ...
    'pe_kalman_innovation', ...
    'pe_latent_curvature', ...
    'pe_belief_update'};
if ~ismember(path_type, valid_path_types)
    error(['path_type must be observed, predicted, prediction_error, pe, ' ...
        'or one of the registered pe_* variants.']);
end
if ~exist('dRSAtypeToRun', 'var') || isempty(dRSAtypeToRun), dRSAtypeToRun = 'corr'; end
if ~exist('pcrStrategy', 'var') || isempty(pcrStrategy), pcrStrategy = 'baseline_pcr_border'; end
if ~exist('doSmoothNeural', 'var') || isempty(doSmoothNeural), doSmoothNeural = true; end
if ~exist('smoothWindowSamples', 'var') || isempty(smoothWindowSamples), smoothWindowSamples = 15; end
if ~exist('doSmoothingPlots', 'var') || isempty(doSmoothingPlots), doSmoothingPlots = false; end
if ~exist('plotSmoothingWindow', 'var') || isempty(plotSmoothingWindow), plotSmoothingWindow = 9; end

handoff = drsa_stage_utils.load_handoff(drsa_handoff_json);
drsa_stage_utils.add_helper_paths(handoff);
if ~exist('plotSampleRateHz', 'var') || isempty(plotSampleRateHz)
    plotSampleRateHz = double(handoff.sampling_rate_hz);
end
if exist('output_root_override', 'var') && ~isempty(output_root_override)
    base_out_dir = char(output_root_override);
else
    base_out_dir = handoff.drsa_dir;
end

identity_values = drsa_stage_utils.vectorize_numeric(handoff.identity_values);
time_axis_sec = drsa_stage_utils.vectorize_numeric(handoff.time_axis_sec);
Obs = drsa_stage_utils.load_models(handoff);
sensor_group_lists = drsa_stage_utils.get_megin_sensor_groups();

%% Analysis loops
for i_cond = 1:numel(conditions_to_run)
    condition_str = lower(strtrim(char(conditions_to_run{i_cond})));
    [neural, channel_labels, ~] = drsa_stage_utils.load_neural_condition(handoff, condition_str);
    [neural, channel_labels, removed_labels] = drsa_stage_utils.remove_all_nan_channels(neural, channel_labels);
    if doSmoothNeural
        neural = smoothdata(neural, 3, 'gaussian', smoothWindowSamples);
    end

    n_time = size(neural, 3);
    %% Build the single stimulus/PE model requested for this alt dRSA run
    % Data flow:
    %   handoff model MAT + requested path_type -> one identity x feature x
    %   time model tensor. Legacy observed/predicted/prediction_error semantics
    %   are preserved; new PE variants are separate model_source values.
    [model_position, model_source, model_source_condition, model_feature] = ...
        local_build_alt_model_for_path_type( ...
        condition_str, path_type, Obs, identity_values, n_time);
    stimulus_model_label = drsa_stage_utils.stimulus_model_label( ...
        condition_str, model_source, model_feature);
    model_axis_label = drsa_stage_utils.model_time_axis_label( ...
        condition_str, model_source, model_feature);

    for i_group = 1:numel(sensor_groups_to_run)
        [sensor_group_key, sensor_group_tag] = drsa_stage_utils.normalize_sensor_group(sensor_groups_to_run{i_group});
        target_labels = string(sensor_group_lists.(sensor_group_key)(:));
        selected_mask = ismember(channel_labels, target_labels);
        selected_channel_labels = channel_labels(selected_mask);
        if ~any(selected_mask)
            error('No channels remain for sensor group %s in condition %s.', ...
                sensor_group_tag, condition_str);
        end

        neural_group = neural(:, selected_mask, :);
        neural_concat = dRSA_concatenate(neural_group, [], 0, 'suppressDispText', 1);
        model_pos = dRSA_concatenate(model_position, [], 0, 'suppressDispText', 1);
        trial_len = size(neural_group, 3);
        [subsamples, trigger_opt] = drsa_stage_utils.build_trial_subsamples(trial_len, size(neural_concat, 2));

        params = drsa_stage_utils.build_drsa_params(dRSAtypeToRun, plotSampleRateHz, trial_len, pcrStrategy);
        params.modelNames = {stimulus_model_label};
        params.modelToTest = 1;
        params.modelDistMeasure = {'euclidean'};
        params.neuralDistMeasure = 'correlation';
        params.modeltoRegressout = {[]};
        params.nIter = size(subsamples, 3);
        autocorr_border = drsa_stage_utils.compute_autocorr_border(params, {model_pos}, subsamples);

        dRSA_neural_position = dRSA_coreFunction(neural_concat, {model_pos}, params, ...
            'CurrSubsamples', subsamples(:, :, 1), ...
            'Autocorrborder', autocorr_border, ...
            'suppressDispText', 1);

        if strcmp(condition_str, 'occluded_deviant')
            out_root = fullfile(base_out_dir, 'matlab_real_neural', 'A_dRSA_alt', ...
                condition_str, lower(model_source), lower(dRSAtypeToRun));
            file_tag = sprintf('A_dRSA_alt_%s_%s_%s_%s', ...
                condition_str, lower(model_source), lower(dRSAtypeToRun), sensor_group_tag);
        else
            out_root = fullfile(base_out_dir, 'matlab_real_neural', 'A_dRSA_alt', ...
                condition_str, lower(dRSAtypeToRun));
            file_tag = sprintf('A_dRSA_alt_%s_%s_%s', ...
                condition_str, lower(dRSAtypeToRun), sensor_group_tag);
        end
        matrices_dir = fullfile(out_root, 'matrices');
        results_dir = fullfile(out_root, 'results');
        if ~isfolder(matrices_dir), mkdir(matrices_dir); end
        if ~isfolder(results_dir), mkdir(results_dir); end

        fig_file = fullfile(matrices_dir, sprintf('%s.png', file_tag));
        drsa_stage_utils.export_matrix_figure(dRSA_neural_position(:, :, 1), ...
            plotSampleRateHz, ...
            sprintf('%s | A_dRSA_alt: %s | %s | %s %s', ...
                handoff.subject_bids_id, condition_str, stimulus_model_label, ...
                dRSAtypeToRun, sensor_group_tag), ...
            fig_file, condition_str, handoff.occlusion_timing, model_axis_label);

        fig_file_smoothed = '';
        if doSmoothingPlots
            fig_file_smoothed = fullfile(matrices_dir, sprintf('%s_smoothed.png', file_tag));
            drsa_stage_utils.export_matrix_figure( ...
                drsa_stage_utils.smooth_matrix_for_plot(dRSA_neural_position(:, :, 1), plotSmoothingWindow), ...
                plotSampleRateHz, ...
                sprintf('%s | A_dRSA_alt smoothed: %s | %s | %s %s', ...
                    handoff.subject_bids_id, condition_str, stimulus_model_label, ...
                    dRSAtypeToRun, sensor_group_tag), ...
                fig_file_smoothed, condition_str, handoff.occlusion_timing, model_axis_label);
        end

        res_file = fullfile(results_dir, sprintf('%s.mat', file_tag));
        % Result arrays are small enough for MATLAB v7 and remain readable from
        % Python scipy for numeric group averaging.
        save(res_file, 'dRSA_neural_position', 'params', 'handoff', ...
            'condition_str', 'path_type', 'model_source', ...
            'model_source_condition', 'model_feature', ...
            'stimulus_model_label', 'model_axis_label', ...
            'sensor_group_key', 'sensor_group_tag', 'selected_channel_labels', ...
            'removed_labels', 'trigger_opt', 'time_axis_sec', 'fig_file', ...
            'fig_file_smoothed', 'doSmoothingPlots', 'plotSmoothingWindow', '-v7');

        fprintf('Saved A_dRSA_alt output (%s, %s):\n  %s\n  %s\n', ...
            condition_str, sensor_group_tag, fig_file, res_file);
    end
end

fprintf('A_dRSA_alt complete.\n');

function [model_tensor, model_source, model_source_condition, model_feature] = ...
        local_build_alt_model_for_path_type( ...
        condition_str, path_type, Obs, identity_values, n_time)
% LOCAL_BUILD_ALT_MODEL_FOR_PATH_TYPE Build one A_dRSA_alt stimulus model.
%
% Inputs:
%   condition_str   : condition requested by Stage 07.
%   path_type       : observed, predicted, prediction_error, or pe_* source.
%   Obs             : observed trajectory MAT payload with xySeqs and Cfg.
%   identity_values : identity axis exported by Stage 06.
%   n_time          : neural/model sample count.
%
% Outputs:
%   model_tensor           : identity x feature x time dRSA model tensor.
%   model_source           : stable source string used in output folders.
%   model_source_condition : readable provenance for the source condition(s).
%   model_feature          : feature label passed to report label helpers.
%
% Data flow:
%   path_type -> observed/predicted trial selection -> tensor construction ->
%   optional PE-variant transform.

if local_is_pe_model_source(path_type)
    if ~strcmp(condition_str, 'occluded_deviant')
        error('%s path_type is valid only for occluded_deviant; got %s.', ...
            path_type, condition_str);
    end

    [observed_trials, ~, observed_center_shift, ~] = ...
        drsa_stage_utils.model_trials_for_condition(condition_str, 'observed', Obs);
    observed_sorted = drsa_stage_utils.sort_and_validate_sequences( ...
        observed_trials, identity_values);
    [observed_position, ~] = drsa_stage_utils.build_position_direction( ...
        observed_sorted, identity_values, n_time, observed_center_shift);

    [predicted_trials, ~, predicted_center_shift, predicted_source_condition] = ...
        drsa_stage_utils.model_trials_for_condition(condition_str, 'predicted', Obs);
    predicted_sorted = drsa_stage_utils.sort_and_validate_sequences( ...
        predicted_trials, identity_values);
    [predicted_position, ~] = drsa_stage_utils.build_position_direction( ...
        predicted_sorted, identity_values, n_time, predicted_center_shift);

    [model_tensor, model_feature] = local_build_pe_variant_tensor( ...
        path_type, observed_position, predicted_position, ...
        observed_sorted, predicted_sorted, Obs.Cfg, n_time);
    model_source = path_type;
    model_source_condition = sprintf('%s-minus-%s', ...
        condition_str, predicted_source_condition);
else
    [trials, model_source, center_shift, model_source_condition] = ...
        drsa_stage_utils.model_trials_for_condition(condition_str, path_type, Obs);
    sorted_trials = drsa_stage_utils.sort_and_validate_sequences(trials, identity_values);
    [model_tensor, ~] = drsa_stage_utils.build_position_direction( ...
        sorted_trials, identity_values, n_time, center_shift);
    model_feature = 'position';
end
end

function tf = local_is_pe_model_source(path_type)
% LOCAL_IS_PE_MODEL_SOURCE Return true for legacy and explicit PE sources.
path_type = lower(strtrim(char(path_type)));
tf = strcmp(path_type, 'prediction_error') || strncmp(path_type, 'pe_', 3);
end

function [model_tensor, model_feature] = local_build_pe_variant_tensor( ...
        path_type, observed_position, predicted_position, ...
        observed_trials, predicted_trials, Cfg, n_time)
% LOCAL_BUILD_PE_VARIANT_TENSOR Build the requested PE model tensor.
%
% The legacy prediction_error source remains the raw signed displacement. New
% variants use deterministic transforms so Stage 07 outputs are reproducible
% and do not depend on a Monte Carlo particle count.
residual = observed_position - predicted_position;

switch lower(strtrim(char(path_type)))
    case 'prediction_error'
        model_tensor = residual;
        model_feature = 'position';
    case 'pe_prior_unconstrained_50'
        model_tensor = local_pe_prior_unconstrained_50(residual, Cfg);
        model_feature = 'position';
    case 'pe_prior_constrained_50'
        model_tensor = local_pe_prior_constrained_50(residual, Cfg);
        model_feature = 'position';
    case 'pe_precision_weighted'
        model_tensor = local_pe_precision_weighted(residual, Cfg);
        model_feature = 'position';
    case 'pe_kalman_innovation'
        model_tensor = local_pe_kalman_innovation(observed_position, predicted_position);
        model_feature = 'position';
    case 'pe_latent_curvature'
        observed_curvature = local_curvature_tensor(observed_trials, n_time);
        predicted_curvature = local_curvature_tensor(predicted_trials, n_time);
        model_tensor = observed_curvature - predicted_curvature;
        model_feature = 'latent_curvature';
    case 'pe_belief_update'
        model_tensor = local_pe_belief_update(residual, Cfg);
        model_feature = 'belief_update';
    otherwise
        error('Unsupported PE path_type: %s', path_type);
end
end

function model_tensor = local_pe_prior_unconstrained_50(residual, Cfg)
% LOCAL_PE_PRIOR_UNCONSTRAINED_50 50% known path plus broad uniform branch.
%
% The known branch is a Gaussian around the expected nondeviant path. The
% unknown branch is uniform over the motion rectangle. The output keeps signed
% residual direction but gates it by the posterior responsibility of the known
% branch and appends a surprise channel.
sigma = local_spatial_sigma(Cfg);
rect_area = local_motion_rect_area(Cfg);
mag_sq = sum(residual .^ 2, 2);
known_density = exp(-0.5 .* mag_sq ./ (sigma .^ 2)) ./ (2 .* pi .* sigma .^ 2);
uniform_density = 1 ./ rect_area;
mixture_density = 0.5 .* known_density + 0.5 .* uniform_density;
responsibility = (0.5 .* known_density) ./ max(mixture_density, realmin);
weighted_residual = bsxfun(@times, residual, responsibility);
surprise = -log(max(mixture_density, realmin));
model_tensor = cat(2, weighted_residual, surprise);
end

function model_tensor = local_pe_prior_constrained_50(residual, Cfg)
% LOCAL_PE_PRIOR_CONSTRAINED_50 50% known path plus empirical deviant branch.
%
% The constrained branch is estimated from the same generated stimulus set:
% at each time point, the possible deviant displacement is approximated by the
% leave-one-out residual distribution across sequence identities. This is a
% deterministic proxy for knowing the experiment's turn/curvature constraints.
loo_mean = local_leave_one_out_mean(residual);
mixture_expected_residual = 0.5 .* loo_mean;
centered_residual = residual - mixture_expected_residual;
sigma = local_timewise_feature_scale(residual, Cfg);
standardized = centered_residual ./ sigma;
surprise = sqrt(sum(standardized .^ 2, 2));
model_tensor = cat(2, centered_residual, surprise);
end

function model_tensor = local_pe_precision_weighted(residual, Cfg)
% LOCAL_PE_PRECISION_WEIGHTED Scale signed PE by empirical predictive precision.
sigma = local_timewise_feature_scale(residual, Cfg);
model_tensor = residual ./ sigma;
end

function model_tensor = local_pe_kalman_innovation(observed_position, predicted_position)
% LOCAL_PE_KALMAN_INNOVATION Simple online innovation with fixed Kalman gain.
%
% The state follows the expected trajectory velocity and is corrected toward
% each observed sample. This produces a transient innovation that decays as the
% observer updates after reappearance.
gain = 0.35;
n_identity = size(observed_position, 1);
n_time = size(observed_position, 3);
model_tensor = zeros(size(observed_position));
for i_id = 1:n_identity
    state_xy = reshape(predicted_position(i_id, :, 1), 1, []);
    for i_time = 1:n_time
        observed_xy = reshape(observed_position(i_id, :, i_time), 1, []);
        innovation_xy = observed_xy - state_xy;
        model_tensor(i_id, :, i_time) = reshape(innovation_xy, 1, 2, 1);
        if i_time < n_time
            expected_step = reshape( ...
                predicted_position(i_id, :, i_time + 1) - predicted_position(i_id, :, i_time), ...
                1, []);
            state_xy = state_xy + expected_step + gain .* innovation_xy;
        end
    end
end
end

function model_tensor = local_pe_belief_update(residual, Cfg)
% LOCAL_PE_BELIEF_UPDATE Convert residual magnitude into latent-cause evidence.
%
% Channel 1 is an approximate posterior that the active path is deviant.
% Channel 2 is the positive frame-to-frame posterior update, which highlights
% when the residual first becomes informative.
sigma = local_spatial_sigma(Cfg);
mag = sqrt(sum(residual .^ 2, 2));
posterior_deviant = 1 - exp(-0.5 .* (mag ./ sigma) .^ 2);
if size(posterior_deviant, 3) < 2
    positive_update = posterior_deviant;
else
    delta = diff(posterior_deviant, 1, 3);
    positive_update = cat(3, posterior_deviant(:, :, 1), max(delta, 0));
end
model_tensor = cat(2, posterior_deviant, positive_update);
end

function loo_mean = local_leave_one_out_mean(tensor)
% LOCAL_LEAVE_ONE_OUT_MEAN Mean across identities excluding the current row.
n_identity = size(tensor, 1);
if n_identity < 2
    loo_mean = zeros(size(tensor));
    return;
end
total = sum(tensor, 1);
loo_mean = bsxfun(@rdivide, bsxfun(@minus, total, tensor), n_identity - 1);
end

function sigma = local_timewise_feature_scale(tensor, Cfg)
% LOCAL_TIMEWISE_FEATURE_SCALE Estimate per-time residual spread with a floor.
scale_floor = local_spatial_sigma(Cfg);
sigma = std(tensor, 0, 1);
sigma = max(sigma, scale_floor);
sigma = repmat(sigma, [size(tensor, 1), 1, 1]);
end

function sigma = local_spatial_sigma(Cfg)
% LOCAL_SPATIAL_SIGMA Resolve a conservative spatial uncertainty floor.
sigma = 0.25;
if isfield(Cfg, 'dot_w') && ~isempty(Cfg.dot_w)
    sigma = max(sigma, double(Cfg.dot_w) / 2);
elseif isfield(Cfg, 'dotWidth') && ~isempty(Cfg.dotWidth)
    sigma = max(sigma, double(Cfg.dotWidth) / 2);
end
if ~isfinite(sigma) || sigma <= 0
    sigma = 0.25;
end
end

function rect_area = local_motion_rect_area(Cfg)
% LOCAL_MOTION_RECT_AREA Return the visual-degree area used by the uniform branch.
rect_area = 100;
if isfield(Cfg, 'rectSize') && numel(Cfg.rectSize) >= 2
    rect_size = double(Cfg.rectSize(:)');
    rect_area = rect_size(1) .* rect_size(2);
end
if ~isfinite(rect_area) || rect_area <= 0
    rect_area = 100;
end
end

function curvature = local_curvature_tensor(sorted_trials, n_time)
% LOCAL_CURVATURE_TENSOR Load saved curvyness or derive signed turn rate.
n_identity = numel(sorted_trials);
curvature = zeros(n_identity, 1, n_time);
for i_id = 1:n_identity
    if isfield(sorted_trials(i_id), 'curvyness') && ...
            ~isempty(sorted_trials(i_id).curvyness)
        values = double(sorted_trials(i_id).curvyness(:));
    else
        values = local_derive_curvature_from_xy(sorted_trials(i_id).xy);
    end
    if numel(values) ~= n_time
        error('Curvature length mismatch for identity index %d: model=%d neural=%d.', ...
            i_id, numel(values), n_time);
    end
    curvature(i_id, 1, :) = reshape(values, 1, 1, []);
end
end

function curvature = local_derive_curvature_from_xy(xy)
% LOCAL_DERIVE_CURVATURE_FROM_XY Fallback signed turn-rate from path samples.
xy = double(xy);
if size(xy, 1) < 3
    curvature = zeros(size(xy, 1), 1);
    return;
end
dx = diff(xy(:, 1), 1, 1);
dy = diff(xy(:, 2), 1, 1);
angles_deg = rad2deg(unwrap(atan2(dy, dx)));
turn_rate = [0; diff(angles_deg)];
curvature = [turn_rate(1); turn_rate(:)];
curvature = curvature(1:size(xy, 1));
end
